            ['question' => 'How much does shipping cost?', 'answer' => 'Standard US shipping is free on every order. There is no minimum order value and no separate handling fee.'],
            ['question' => 'How long does delivery take?', 'answer' => 'Orders are processed in 1-3 business days after purchase. Standard transit usually takes 3-7 business days, so the estimated delivery window is about 4-10 business days total from the order date.'],
